+const form = document.querySelector('#support-form');
+const statusMessage = document.querySelector('#form-status');
+
+const fields = [
+  {
+    input: document.querySelector('#full-name'),
+    error: document.querySelector('#full-name-error'),
+    validate(value) {
+      if (!value.trim()) {
+        return 'Error: Enter your full name.';
+      }
+      return '';
+    }
+  },
+  {
+    input: document.querySelector('#email-address'),
+    error: document.querySelector('#email-address-error'),
+    validate(value) {
+      if (!value.trim()) {
+        return 'Error: Enter your email address.';
+      }
+
+      const isValidEmail = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value);
+      if (!isValidEmail) {
+        return 'Error: Enter a valid email address, like name@example.com.';
+      }
+
+      return '';
+    }
+  },
+  {
+    input: document.querySelector('#phone-number'),
+    error: document.querySelector('#phone-number-error'),
+    validate(value) {
+      if (!value.trim()) {
+        return '';
+      }
+
+      const isValidPhone = /^\+?[0-9]{10,15}$/.test(value.trim());
+      if (!isValidPhone) {
+        return 'Error: Enter a phone number with 10 to 15 digits, optionally starting with +.';
+      }
+
+      return '';
+    }
+  }
+];
+
+function setFieldError(field, message) {
+  field.error.textContent = message;
+  field.error.hidden = !message;
+
+  if (message) {
+    field.input.setAttribute('aria-invalid', 'true');
+  } else {
+    field.input.removeAttribute('aria-invalid');
+  }
+}
+
+function validateField(field) {
+  const message = field.validate(field.input.value);
+  setFieldError(field, message);
+  return !message;
