          <label for="email-address">Email address <span aria-hidden="true">*</span></label>
          <input
            id="email-address"
            name="emailAddress"
            type="email"
            inputmode="email"
            autocomplete="email"
            required
            aria-describedby="email-address-error"
          >
          <p id="email-address-error" class="field-message" hidden></p>
        </div>

        <div class="form-field">
          <label for="phone-number">Phone number <span class="optional-text">(optional)</span></label>
          <input
