 <!DOCTYPE html>
 <html lang="en">
 <head>
   <meta charset="UTF-8">
   <meta name="viewport" content="width=device-width, initial-scale=1.0">
   <title>Support contact form</title>
   <style>
     :root {
       --color-bg: #0d1117;
       --color-panel: #161b22;
       --color-panel-strong: #1f2937;
       --color-text: #f3f4f6;
       --color-muted-text: #9ca3af;
       --color-border: #374151;
       --color-border-strong: #4b5563;
       --color-focus: #7dd3fc;
       --color-accent: #8b5cf6;
       --color-danger: #fca5a5;
       --color-success: #86efac;
     }

     * {
       box-sizing: border-box;
     }

     body {
       margin: 0;
       min-height: 100vh;
       font-family: Arial, Helvetica, sans-serif;
       background:
         radial-gradient(circle at top, #1f2937 0, var(--color-bg) 40%),
         var(--color-bg);
       color: var(--color-text);
     }

     .skip-link {
       position: absolute;
       left: 1rem;
       top: 1rem;
       transform: translateY(-200%);
       padding: 0.75rem 1rem;
       border-radius: 0.75rem;
       background: var(--color-text);
       color: var(--color-bg);
       font-weight: 700;
     }

     .skip-link:focus {
       transform: translateY(0);
       outline: 3px solid var(--color-focus);
       outline-offset: 3px;
     }

     main {
       padding: 2rem 1rem;
     }

     .page-shell {
       width: min(100%, 40rem);
       margin: 0 auto;
       padding: clamp(1.5rem, 4vw, 2.5rem);
       border: 1px solid var(--color-border);
       border-radius: 1.5rem;
       background: linear-gradient(180deg, var(--color-panel-strong), var(--color-panel));
       box-shadow: 0 1.5rem 4rem rgb(0 0 0 / 0.35);
     }

     .content-block {
       margin-bottom: 1.75rem;
     }

     .eyebrow {
       margin: 0 0 0.5rem;
       color: var(--color-focus);
       font-size: 0.875rem;
       font-weight: 700;
       letter-spacing: 0.08em;
       text-transform: uppercase;
     }

     h1 {
       margin: 0 0 0.75rem;
       font-size: clamp(2rem, 5vw, 2.75rem);
       line-height: 1.1;
     }

     .intro,
     .required-note {
       margin: 0;
       color: var(--color-muted-text);
     }

     .contact-form {
       display: grid;
       gap: 1rem;
     }

     .form-field {
       display: grid;
       gap: 0.45rem;
     }

     label {
       font-weight: 700;
     }

     .optional-text {
       color: var(--color-muted-text);
       font-weight: 400;
     }

     input {
       width: 100%;
       padding: 0.9rem 1rem;
       border: 1px solid var(--color-border);
       border-radius: 0.9rem;
       background: #0f172a;
       color: var(--color-text);
       font: inherit;
     }

     input:hover {
       border-color: var(--color-border-strong);
     }

     input:focus-visible,
     button:focus-visible {
       outline: 3px solid transparent;
       box-shadow: 0 0 0 3px var(--color-focus);
     }

     input[aria-invalid="true"] {
       border-color: var(--color-danger);
     }

     .helper-text,
     .field-message,
     .form-status {
       margin: 0;
       font-size: 0.95rem;
       line-height: 1.5;
     }

     .helper-text {
       color: var(--color-muted-text);
     }

     .field-message {
       color: var(--color-danger);
     }

     button {
       justify-self: start;
       padding: 0.95rem 1.4rem;
       border: 1px solid transparent;
       border-radius: 999px;
       background: linear-gradient(135deg, var(--color-accent), #2563eb);
       color: var(--color-text);
       font: inherit;
       font-weight: 700;
       cursor: pointer;
     }

     button:hover {
       filter: brightness(1.08);
     }

     .form-status {
       min-height: 1.5rem;
       color: var(--color-success);
     }

     @media (max-width: 32rem) {
       main {
         padding: 1rem;
       }

       .page-shell {
         border-radius: 1rem;
       }

       button {
         width: 100%;
         justify-self: stretch;
       }
     }

     @media (forced-colors: active) {
       .skip-link,
       .page-shell,
       input,
       button {
         border: 1px solid ButtonBorder;
       }

       .skip-link,
       .page-shell,
       input,
       button {
         background: Canvas;
         color: CanvasText;
       }

       .eyebrow {
         color: LinkText;
       }

       .field-message,
       .form-status {
         color: CanvasText;
       }
     }
   </style>
 </head>
 <body>
   <a class="skip-link" href="#maincontent">Skip to main content</a>
   <main id="maincontent" tabindex="-1">
     <section class="page-shell" aria-labelledby="page-title">
       <div class="content-block">
         <p class="eyebrow">Support</p>
         <h1 id="page-title">Contact our support team</h1>
         <p class="intro">
           Share your details and we will follow up as soon as possible.
         </p>
       </div>

       <form id="support-form" class="contact-form" novalidate>
         <p class="required-note"><span aria-hidden="true">*</span> Required fields</p>

         <div class="form-field">
           <label for="full-name">Full name <span aria-hidden="true">*</span></label>
           <input
             id="full-name"
             name="fullName"
             type="text"
             autocomplete="name"
             required
             aria-describedby="full-name-error"
           >
           <p id="full-name-error" class="field-message" hidden></p>
         </div>

         <div class="form-field">
           <label for="email-address">Email address <span aria-hidden="true">*</span></label>
           <input
             id="email-address"
             name="emailAddress"
             type="email"
             inputmode="email"
             autocomplete="email"
             required
             aria-describedby="email-address-error"
           >
           <p id="email-address-error" class="field-message" hidden></p>
         </div>

         <div class="form-field">
           <label for="phone-number">Phone number <span class="optional-text">(optional)</span></label>
           <input
             id="phone-number"
             name="phoneNumber"
             type="tel"
             inputmode="tel"
             autocomplete="tel"
             aria-describedby="phone-number-help phone-number-error"
           >
           <p id="phone-number-help" class="helper-text">Use digits only, for example 2025550147 or +12025550147.</p>
           <p id="phone-number-error" class="field-message" hidden></p>
         </div>

         <button type="submit">Send support request</button>
         <p id="form-status" class="form-status" role="status" aria-live="polite"></p>
       </form>
     </section>
   </main>

   <script>
     const form = document.querySelector('#support-form');
     const statusMessage = document.querySelector('#form-status');

     const fields = [
       {
         input: document.querySelector('#full-name'),
         error: document.querySelector('#full-name-error'),
         validate(value) {
           if (!value.trim()) {
             return 'Error: Enter your full name.';
           }
           return '';
         }
       },
       {
         input: document.querySelector('#email-address'),
         error: document.querySelector('#email-address-error'),
         validate(value) {
           if (!value.trim()) {
             return 'Error: Enter your email address.';
           }

           const isValidEmail = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value);
           if (!isValidEmail) {
             return 'Error: Enter a valid email address, like name@example.com.';
           }

           return '';
         }
       },
       {
         input: document.querySelector('#phone-number'),
         error: document.querySelector('#phone-number-error'),
         validate(value) {
           if (!value.trim()) {
             return '';
           }

           const isValidPhone = /^\+?[0-9]{10,15}$/.test(value.trim());
           if (!isValidPhone) {
             return 'Error: Enter a phone number with 10 to 15 digits, optionally starting with +.';
           }

           return '';
         }
       }
     ];

     function setFieldError(field, message) {
       field.error.textContent = message;
       field.error.hidden = !message;

       if (message) {
         field.input.setAttribute('aria-invalid', 'true');
       } else {
         field.input.removeAttribute('aria-invalid');
       }
     }

     function validateField(field) {
       const message = field.validate(field.input.value);
       setFieldError(field, message);
       return !message;
     }

     fields.forEach((field) => {
       field.input.addEventListener('input', () => {
         if (!field.error.hidden || field.input.getAttribute('aria-invalid') === 'true') {
           validateField(field);
         }

         if (statusMessage.textContent) {
           statusMessage.textContent = '';
         }
       });
     });

     form.addEventListener('submit', (event) => {
       event.preventDefault();

       const invalidField = fields.find((field) => !validateField(field));

       if (invalidField) {
         statusMessage.textContent = 'Please correct the highlighted fields and try again.';
         invalidField.input.focus();
         return;
       }

       statusMessage.textContent = 'Your support request is ready to send.';
       form.reset();
       fields.forEach((field) => setFieldError(field, ''));
     });
   </script>
 </body>
 </html>

